"""Timing indices by name, for a sketch that does not compile in the table.

A sketch that UPLOADS its table still has to name a few timing entries: the
transitional session sketch pushes the START line's holds and windows into the
table, and it has to know which slots those are.

WHY THIS IS GENERATED AND NOT WRITTEN DOWN. The index of `t_resp_win` is a
consequence of how many entries a spec declares before it. Adding one timing
entry to the YAML renumbers everything after it, and a sketch holding the old
number would then push the response window into whatever now occupies slot 5 --
silently, with no build error and no CRC failure, because the table is perfectly
valid and the sketch is writing a legal value into a legal slot.

That is the same class of bug as every other mirrored constant this project has
retired, with a worse signature: it changes a duration rather than breaking a
build.

Emitted per spec, because the numbering is per spec. Only the specs a checked-in
sketch actually runs need one.
"""

from __future__ import annotations

from taskgraph.pipeline import compile_spec
from taskgraph.table import StateTable

#: spec id -> the sketch directory that includes its indices header.
#: Deliberately explicit: a header generated for a spec nothing includes is
#: clutter, and one a sketch includes and codegen does not emit is a build break.
SKETCHES = {"grgl_2odor": "TaskRunner_GRGL"}


def emit_header(table: StateTable) -> str:
    out = [
        f"/* GENERATED by taskgraph/codegen/indices.py from specs/{table.spec_id}.yaml",
        " * — DO NOT EDIT. Regenerate with `taskgraph codegen`.",
        " *",
        " * Timing entries by name. A spec that gains an entry renumbers everything",
        " * after it, and a sketch holding an old number would push a duration into",
        " * the wrong slot -- silently, since the table stays valid and the value stays",
        " * legal. That is why these are generated rather than written down.",
        " */",
        "",
        f"#ifndef TG_IDX_{table.spec_id.upper()}_H",
        f"#define TG_IDX_{table.spec_id.upper()}_H",
        "",
        f'#define TG_SPEC_ID "{table.spec_id}"',
        f'#define TG_SPEC_HASH "{table.spec_hash[:8]}"',
        "",
    ]
    width = max(len(t) for t in table.timing_ids) + 6
    for i, tid in enumerate(table.timing_ids):
        sym = f"TG_IDX_{tid.removeprefix('t_').upper()}"
        out.append(f"#define {sym:<{width}} {i}  // {table.timing[i]} ms")
    out.append("")
    out.append(f"#endif  /* TG_IDX_{table.spec_id.upper()}_H */")
    return "\n".join(out) + "\n"


def outputs(arduino_root) -> dict:
    made = {}
    for spec_id, sketch in SKETCHES.items():
        r = compile_spec(arduino_root.parent / "specs" / f"{spec_id}.yaml")
        if not r.ok:  # pragma: no cover - a broken spec fails louder elsewhere
            raise AssertionError(f"{spec_id} does not compile: {r.bag.render()}")
        made[arduino_root / sketch / f"{spec_id.split('_')[0]}_indices.h"] = emit_header(r.table)
    return made
